// useOnlineStatus.js.
import { useEffect, useState } from "react";

export function useOnlineStatus() {
  const [isOnline, setIsOnline] = useState(() => navigator.onLine);
  useEffect(() => {
    const update = () => setIsOnline(navigator.onLine);
    window.addEventListener("online", update);
    window.addEventListener("offline", update);
    return () => {
      window.removeEventListener("online", update);
      window.removeEventListener("offline", update);
    };
  }, []);
  return isOnline;
}

// Two consumers, each with its own subscription.
function OfflineBanner() {
  const isOnline = useOnlineStatus();
  return isOnline ? null : <p role="status">You're offline. Changes will save when you reconnect.</p>;
}

function SaveButton({ onSave }) {
  const isOnline = useOnlineStatus();
  return <button type="button" onClick={onSave} disabled={!isOnline}>{isOnline ? "Save" : "Offline"}</button>;
}
```

